/** Image module declarations for TypeScript (React Native) */
declare module '*.png' {
  const src: import('react-native').ImageSourcePropType;
  export default src;
}
declare module '*.jpg' {
  const src: import('react-native').ImageSourcePropType;
  export default src;
}
declare module '*.jpeg' {
  const src: import('react-native').ImageSourcePropType;
  export default src;
}
declare module '*.webp' {
  const src: import('react-native').ImageSourcePropType;
  export default src;
}
